import BounceBool.*

object TrampolineExample {
  def evenStep(n: Int): Bounce =
    if (n == 0) done(true) else more(oddStep, n - 1)
  def oddStep(n: Int): Bounce =
    if (n == 0) done(false) else more(evenStep, n - 1)
  def parity(n: Int): Boolean = run(evenStep(n))
}

object BounceBool {
  enum Bounce {
    case Done(answer: Boolean)
    case More(next: Int => Bounce, argument: Int)
  }
  def done(answer: Boolean): Bounce = Bounce.Done(answer)
  def more(next: Int => Bounce, argument: Int): Bounce =
    Bounce.More(next, argument)
  @annotation.tailrec
  def run(current: Bounce): Boolean = current match {
    case Bounce.Done(answer) => answer
    case Bounce.More(next, argument) => run(next(argument))
  }
}

import AroundInt.around

object ExecuteAroundExample {
  final case class Resource(value: Int)
  final class ResourceFailure extends RuntimeException
  def run(mode: Int): Int = {
    var events = 0
    def note(n: Int): Unit = { events = events * 10 + n }
    try {
      val value = around(
        () => {
          note(1)
          if (mode == 2) throw new ResourceFailure
          Resource(42)
        },
        (_: Resource) => note(3),
        (resource: Resource) => {
          note(2)
          if (mode == 1) throw new ResourceFailure
          resource.value
        })
      value * 1000 + events
    } catch {
      case _: ResourceFailure => -events
    }
  }
}

object AroundInt {
  def around[R](acquire: () => R,
                release: R => Unit,
                action: R => Int): Int = {
    val resource = acquire()
    try action(resource)
    finally release(resource)
  }
}

import CurryInt.capture

object CurryingExample {
  def add(first: Int, second: Int): Int = first + second
  def demo: Int = {
    val add5 = capture(add, 5)
    val add100 = capture(add, 100)
    add5(1) * 1000000 + add100(1) * 1000 + add5(1)
  }
}

object CurryInt {
  def capture(binary: (Int, Int) => Int, first: Int): Int => Int =
    second => binary(first, second)
}
